using System.Net;using System.Net.Sockets;using System.Security.Cryptography;using System.Text;using OmniToolbox.LocalModules;
int checks=0;void Check(bool b,string message){if(!b)throw new Exception(message);checks++;Console.WriteLine("PASS "+message);}bool Reject(Action a){try{a();return false;}catch(CryptographicException){return true;}}
string folder=args.Length>0?args[0]:Path.GetTempPath();Directory.CreateDirectory(folder);if(args.Contains("--verify-java")){byte[] k=Convert.FromBase64String(File.ReadAllText(Path.Combine(folder,"fixture-key.txt")));byte[] plain=PhoneUdpVideoSession.Open(k,false,File.ReadAllBytes(Path.Combine(folder,"java-client.bin")));Check(Encoding.UTF8.GetString(plain)=="cross-language-确认","Java AES-GCM packet decrypts in .NET with matching AAD and nonce");return;}
if(args.Contains("--serve-capture")){byte[] raw=File.ReadAllBytes(Path.Combine(folder,"capture.h264"));var starts=new List<int>();for(int i=0;i<raw.Length-5;i++){int n=raw[i]==0&&raw[i+1]==0&&raw[i+2]==1?3:raw[i]==0&&raw[i+1]==0&&raw[i+2]==0&&raw[i+3]==1?4:0;if(n>0&&(raw[i+n]&31)==9){starts.Add(i);i+=n;}}var units=new List<byte[]>();for(int i=0;i<starts.Count-1;i++)units.Add(raw[starts[i]..starts[i+1]]);int videoPort;using(var probe=new UdpClient(new IPEndPoint(IPAddress.Loopback,0)))videoPort=((IPEndPoint)probe.Client.LocalEndPoint).Port;using var videoHost=new PhoneUdpVideoSession(videoPort,8000000,60,()=>{},()=>{},()=>{});File.WriteAllText(Path.Combine(folder,"connection.txt"),videoPort+"\n"+videoHost.Secret);for(int i=0;i<360;i++){videoHost.Offer(units[i%units.Count]);await Task.Delay(17);}Console.WriteLine("Real capture UDP replay completed");return;}
if(args.Contains("--serve")){int livePort;using(var probe=new UdpClient(new IPEndPoint(IPAddress.Loopback,0)))livePort=((IPEndPoint)probe.Client.LocalEndPoint).Port;using var host=new PhoneUdpVideoSession(livePort,8000000,60,()=>{},()=>{},()=>{});File.WriteAllText(Path.Combine(folder,"connection.txt"),livePort+"\n"+host.Secret);byte[] f=new byte[20003];new byte[]{0,0,0,1,0x65}.CopyTo(f,0);for(int i=0;i<180;i++){host.Offer(f);await Task.Delay(33);}return;}
byte[] key=Enumerable.Range(0,32).Select(i=>(byte)i).ToArray(),payload=Encoding.UTF8.GetBytes("H264-test-中文");byte[] packet=PhoneUdpVideoSession.Seal(key,true,3,1,0,1,1,1,payload.Length,payload);Check(PhoneUdpVideoSession.Open(key,true,packet).SequenceEqual(payload),"AEAD payload roundtrip");var tamper=packet.ToArray();tamper[5]^=1;Check(Reject(()=>PhoneUdpVideoSession.Open(key,true,tamper)),"header metadata tampering rejected");tamper=packet.ToArray();tamper[^1]^=1;Check(Reject(()=>PhoneUdpVideoSession.Open(key,true,tamper)),"ciphertext/tag tampering rejected");Check(Reject(()=>PhoneUdpVideoSession.Open(key,false,packet)),"direction nonce domains cannot be reflected");Check(Reject(()=>PhoneUdpVideoSession.Open(new byte[32],true,packet)),"wrong session key rejected");Check(Reject(()=>PhoneUdpVideoSession.Open(key,true,new byte[1201])),"oversized datagram rejected before decrypt");
int port;using(var probe=new UdpClient(new IPEndPoint(IPAddress.Loopback,0)))port=((IPEndPoint)probe.Client.LocalEndPoint).Port;int touches=0,losses=0,slow=0;using var session=new PhoneUdpVideoSession(port,8000000,60,()=>Interlocked.Increment(ref touches),()=>Interlocked.Increment(ref losses),()=>Interlocked.Increment(ref slow));using var client=new UdpClient(new IPEndPoint(IPAddress.Loopback,0));client.Connect(IPAddress.Loopback,port);key=Convert.FromBase64String(session.Secret);File.WriteAllText(Path.Combine(folder,"fixture-key.txt"),Convert.ToBase64String(key));byte[] proof=Enumerable.Range(10,16).Select(i=>(byte)i).ToArray();long sequence=0;async Task Send(int type,byte[] body)=>await client.SendAsync(PhoneUdpVideoSession.Seal(key,false,type,0,0,0,0,++sequence,0,body));async Task<byte[]> Receive(){using var timeout=new CancellationTokenSource(2000);return (await client.ReceiveAsync(timeout.Token)).Buffer;}
await Send(1,proof);var ack=await Receive();var challenge=PhoneUdpVideoSession.Open(key,true,ack);Check(challenge.Length==32&&challenge.AsSpan(0,16).SequenceEqual(proof),"encrypted handshake echoes client proof");Check(ack.Length<=proof.Length+64,"unverified endpoint receives bounded challenge only");byte[] frame=new byte[20003];Random.Shared.NextBytes(frame);new byte[]{0,0,0,1,0x65}.CopyTo(frame,0);session.Offer(frame);await Task.Delay(50);Check(session.Packets==0,"video cannot amplify before challenge confirmation");byte[] ping=new byte[32];challenge.AsSpan(16,16).CopyTo(ping);await Send(6,ping);await Receive();Check(touches>0,"authenticated endpoint activates session heartbeat");session.Offer(frame);int count=(frame.Length+PhoneUdpVideoSession.Chunk-1)/PhoneUdpVideoSession.Chunk,total=count+(count+7)/8;using(var fixture=File.Create(Path.Combine(folder,"csharp-packets.bin"))){for(int i=0;i<total;i++){var b=await Receive();Check(b.Length<=1200,"video datagram fits 1200-byte MTU budget");byte[] p=PhoneUdpVideoSession.Open(key,true,b);fixture.Write(BitConverter.GetBytes(b.Length));fixture.Write(b);}}File.WriteAllBytes(Path.Combine(folder,"expected-frame.bin"),frame);Check(session.Packets==total,"each group includes one encrypted XOR parity packet");var replay=PhoneUdpVideoSession.Seal(key,false,6,0,0,0,0,sequence,0,ping);int before=touches;await client.SendAsync(replay);await Task.Delay(50);Check(touches==before,"replayed keepalive cannot refresh authority");System.Buffers.Binary.BinaryPrimitives.WriteInt32BigEndian(ping.AsSpan(16),100);System.Buffers.Binary.BinaryPrimitives.WriteInt32BigEndian(ping.AsSpan(20),20);await Send(6,ping);await Receive();Check(slow==1,"measured high loss requests congestion adaptation");Console.WriteLine(checks+" UDP protocol checks passed on loopback; no game input sent");
